// ---------- cyber fx: glow lines, flowing trails, peak ripples (before init)
const RM=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const dv=v=>v==null?null:(typeof v==='object'?(Array.isArray(v)?v[v.length-1]:v.value):v);
const optOf=id=>(charts.find(c=>c[0]===id)||[])[1];
const sArr=o=>Array.isArray(o.series)?o.series:[o.series];
charts.forEach(([id,o])=>{if(!o||!o.series)return;sArr(o).forEach(s=>{if(s.type==='line'){s.lineStyle=Object.assign({width:2},s.lineStyle||{});const c=s.lineStyle.color||(s.itemStyle&&s.itemStyle.color);s.lineStyle.shadowBlur=s.lineStyle.shadowBlur||10;s.lineStyle.shadowColor=s.lineStyle.shadowColor||(typeof c==='string'?c+'aa':'rgba(0,229,255,.55)')}
 if(s.type==='bar'||s.type==='pictorialBar'){s.itemStyle=Object.assign({},s.itemStyle||{});}});if(RM)o.animation=false;else{o.animationDuration=1200;o.animationEasing='cubicOut';o.animationDelay=(i)=>i*12}});
function trail(id,si,color,period){const o=optOf(id);if(!o||RM)return;const ss=sArr(o);const s=ss[si];if(!s||!Array.isArray(s.data))return;const pts=s.data.map((v,i)=>[i,dv(v)]).filter(p=>p[1]!=null&&!isNaN(p[1]));if(pts.length<2)return;
 ss.push({type:'lines',coordinateSystem:'cartesian2d',xAxisIndex:s.xAxisIndex||0,yAxisIndex:s.yAxisIndex||0,polyline:true,silent:true,z:5,zlevel:1,data:[{coords:pts}],lineStyle:{width:0,opacity:0},effect:{show:true,period:period||5,trailLength:.35,symbol:'circle',symbolSize:5,color:color||'#e6ffff',loop:true},tooltip:{show:false}});o.series=ss}
function ripple(id,si,color){const o=optOf(id);if(!o||RM)return;const ss=sArr(o);const s=ss[si];if(!s||!Array.isArray(s.data))return;let bi=-1,bv=-Infinity;s.data.forEach((v,i)=>{const x=dv(v);if(x!=null&&x>bv){bv=x;bi=i}});if(bi<0)return;
 ss.push({type:'effectScatter',xAxisIndex:s.xAxisIndex||0,yAxisIndex:s.yAxisIndex||0,data:[[bi,bv]],symbolSize:9,z:6,rippleEffect:{brushType:'stroke',scale:3.2,period:3},itemStyle:{color:color||'#ff2e4d',shadowBlur:12,shadowColor:color||'#ff2e4d'},tooltip:{show:false},silent:true});o.series=ss}
const firstLine=id=>{const o=optOf(id);if(!o)return -1;return sArr(o).findIndex(s=>s.type==='line')};
const lastLine=id=>{const o=optOf(id);if(!o)return -1;const a=sArr(o);for(let i=a.length-1;i>=0;i--)if(a[i].type==='line')return i;return -1};
[['c_ov_ev','#e6ffff',5,'#00e5ff'],['c_tr_daily','#ffd36b',4.5,'#ff2e4d'],['c_eps','#e6ffff',9,'#a3ff12'],['c_inc_hour',null,0,'#ff2e4d']].forEach(([id,tc,per,rc])=>{const si=id==='c_tr_daily'?lastLine(id):firstLine(id);if(si<0)return;ripple(id,si,rc);if(tc&&id!=='c_eps')trail(id,si,tc,per)});

