// ---------- motion: reveal, count-up, ticker (after mount)
(function(){const RMm=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
 const tk=document.querySelector('.ticker');
 const nums=[...document.querySelectorAll('.hero-big b,.stat .v')];
 function countUp(el){if(el.dataset.done)return;el.dataset.done=1;const t=el.textContent;const m=t.match(/^(\D*?)(\d[\d,]*\.?\d*)(.*)$/s);if(!m)return;const target=parseFloat(m[2].replace(/,/g,''));if(!isFinite(target)||target===0)return;const dec=(m[2].split('.')[1]||'').length;const comma=m[2].includes(',');const t0=performance.now(),dur=1100;
  const f=n=>{let s=n.toFixed(dec);if(comma)s=Number(s).toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});return m[1]+s+m[3]};
  (function step(now){const p=Math.min(1,(now-t0)/dur);const e=1-Math.pow(1-p,3);el.textContent=f(target*e);if(p<1)requestAnimationFrame(step);else el.textContent=t})(t0)}
 if(RMm||!('IntersectionObserver' in window)){if(tk)tk.textContent=tk.dataset.text;return}
 const els=[...document.querySelectorAll('.card,.stat,.story,.find,.case,.sec-head')];els.forEach(e=>{if(e.getBoundingClientRect().top>innerHeight)e.classList.add('rv')});
 const io=new IntersectionObserver(es=>es.forEach(en=>{if(!en.isIntersecting)return;const el=en.target;if(el.classList.contains('rv'))el.classList.add('in');el.querySelectorAll&&el.querySelectorAll('.hero-big b,.stat .v').forEach(countUp);if(el.matches('.hero-big b,.stat .v'))countUp(el);io.unobserve(el)}),{rootMargin:'0px 0px -6% 0px',threshold:.08});
 els.forEach(e=>io.observe(e));nums.forEach(e=>io.observe(e));
 if(tk){const s=tk.dataset.text||'';let i=0;(function ty(){tk.textContent=s.slice(0,i);i+=2;if(i<=s.length+1)setTimeout(ty,22)})()}
 window.__ANIM=1})();
